public class StrBuilder_appendFixedWidthPadLeft_TriageGen2Test {















    @Test
    public void testAppendFixedWidthPadLeft_ToStringReturnsNull() {
        // This tests the 'if (str == null) { str = ""; }' branch.
        // Since we can't easily make obj.toString() return null in standard Java,
        // we rely on the fact that if getNullText() returns null, it handles it.
        StrBuilder sb = new StrBuilder();
        sb.setNullText(null);
        // obj=null -> str=null -> str=""
        // width=3, padChar='x' -> "xxx"
        sb.appendFixedWidthPadLeft(null, 3, 'x');
        assertEquals("xxx", sb.toString());
    }
